                "application": str(destination / "application"),
                "archive_sha256": file_digest(archive_path), "members": len(manifest["members"]),
                "selection": manifest["selection"], "identity": "MATCH"}
    finally:
        if pending is not None:
            shutil.rmtree(pending)

